"""Package the management-shell reconciler for the existing Authentik worker."""
from pathlib import Path
import yaml

class Literal(str):
    pass

yaml.SafeDumper.add_representer(Literal, lambda dumper, value: dumper.represent_scalar(
    'tag:yaml.org,2002:str', value, style='|'))
root = Path(__file__).resolve().parent
(root.parent / 'access-control.yaml').write_text(
    '# Generated by access-control/render-configmap.py. Edit access-control/reconcile.py.\n'
    + yaml.safe_dump({
        'apiVersion': 'v1', 'kind': 'ConfigMap',
        'metadata': {'name': 'authentik-access-control', 'namespace': 'authentik',
                     'annotations': {'argocd.argoproj.io/sync-wave': '-5'}},
        'data': {'reconcile.py': Literal((root / 'reconcile.py').read_text())},
    }, sort_keys=False))
